cd /app; cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
# form URLs must use only query keys allowed by the function URL (A-Za-z0-9_.-)
for f in event seat refund; do
  bash bin/render "$f" | grep -o 'action="[^"]*"' | while read -r l; do
    q=${l#*\?}; q=${q%\"}; k=${q%%=*}
    [[ "$k" =~ ^[A-Za-z0-9_.-]+$ ]] || exit 1
  done || { echo "query key invalid in $f"; fail=1; }
done
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
bash bin/handle POST '/events/1/edit?/save' | grep -q '^200 save' || { echo "handle legacy"; fail=1; }
exit $fail
EOF
bash tests/forms_test.sh; echo $?
cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The key must stay within A-Za-z0-9_.- : the Cirrus function URL rejects other characters (e.g. "/") with 400.
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing. The legacy "?/name" form is still accepted.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; /*) echo "${1#/}" ;; esac; }
EOF
sed -i 's|`?/<操作名>`|`?action=<操作名>`（キーに `/` は使えない。Cirrus の関数 URL が 400 を返すため。旧形式 `?/<操作名>` は受理のみ）|' docs/framework.md
bash scripts/verify.sh; echo $?
